<?php session_start();require_once 'config/conexao.php';require_once 'config/auth.php';exigir_cargo(['administrador','gerente']);
if($_SERVER['REQUEST_METHOD']==='POST'){ $acao=$_POST['acao']??'';if($acao==='salvar'){ $id=(int)($_POST['id']??0);$nome=trim($_POST['nome']??'');$desc=trim($_POST['descricao']??'');$qtd=(float)($_POST['quantidade']??0);$un=trim($_POST['unidade']??'un');$preco=(float)($_POST['preco']??0);if($nome){if($id){$s=$pdo->prepare('UPDATE produtos SET nome=?,descricao=?,quantidade=?,unidade=?,preco=? WHERE id=?');$s->execute([$nome,$desc,$qtd,$un,$preco,$id]);}else{$s=$pdo->prepare('INSERT INTO produtos(nome,descricao,quantidade,unidade,preco) VALUES(?,?,?,?,?)');$s->execute([$nome,$desc,$qtd,$un,$preco]);}flash('Produto salvo.');}}elseif($acao==='movimentar'){ $id=(int)$_POST['id'];$mov=(float)$_POST['movimento'];$tipo=$_POST['tipo'];if($mov>0 && in_array($tipo,['entrada','saida'],true)){$delta=$tipo==='entrada'?$mov:-$mov;$s=$pdo->prepare('UPDATE produtos SET quantidade=quantidade+? WHERE id=? AND quantidade+?>=0');$s->execute([$delta,$id,$delta]);flash($s->rowCount()?'Movimentação registrada.':'Quantidade insuficiente.');}}elseif($acao==='desativar'){ $pdo->prepare('UPDATE produtos SET ativo=IF(ativo=1,0,1) WHERE id=?')->execute([(int)$_POST['id']]);flash('Status do produto alterado.');}header('Location: estoque.php');exit;}
$edit=null;if(isset($_GET['editar'])){$s=$pdo->prepare('SELECT * FROM produtos WHERE id=?');$s->execute([(int)$_GET['editar']]);$edit=$s->fetch();}$prod=$pdo->query('SELECT * FROM produtos ORDER BY nome')->fetchAll(); ?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Estoque</title><link rel="stylesheet" href="style.css"></head><body><main class="app"><header class="topbar"><h2>Estoque</h2><a class="link-sair" href="painel.php">← Painel</a></header><section class="content"><?php mostrar_flash();?><?php if($_SESSION['usuario']['nivel']!=='funcionario'):?><h1><?= $edit?'Editar produto':'Cadastrar produto'?></h1><form class="form-box" method="post"><input type="hidden" name="acao" value="salvar"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><label>Nome do produto</label><input name="nome" required value="<?=h($edit['nome']??'')?>"><label>Descrição</label><textarea name="descricao"><?=h($edit['descricao']??'')?></textarea><div class="form-row"><div><label>Quantidade</label><input type="number" step="0.01" name="quantidade" value="<?=h($edit['quantidade']??0)?>"></div><div><label>Unidade</label><input name="unidade" value="<?=h($edit['unidade']??'un')?>"></div><div><label>Preço (R$)</label><input type="number" step="0.01" name="preco" value="<?=h($edit['preco']??0)?>"></div></div><button>Salvar produto</button></form><?php endif;?><h2>Produtos</h2><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Qtd.</th><th>Un.</th><th>Preço</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($prod as $x):?><tr><td><?=h($x['nome'])?></td><td><?=h($x['quantidade'])?></td><td><?=h($x['unidade'])?></td><td>R$ <?=number_format($x['preco'],2,',','.')?></td><td><?=$x['ativo']?'Ativo':'Desativado'?></td><td><?php if($_SESSION['usuario']['nivel']==='gerente'||$_SESSION['usuario']['nivel']==='administrador'):?><a href="?editar=<?=$x['id']?>">Editar</a><form class="inline" method="post"><input type="hidden" name="acao" value="desativar"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="mini"><?=$x['ativo']?'Desativar':'Ativar'?></button></form><form class="inline" method="post"><input type="hidden" name="acao" value="movimentar"><input type="hidden" name="id" value="<?=$x['id']?>"><input class="qty" name="movimento" type="number" step="0.01" min="0.01" placeholder="Qtd" required><select name="tipo"><option value="entrada">Entrada</option><option value="saida">Saída</option></select><button class="mini">Movimentar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>